-- 1. TABLAS PRINCIPALES
CREATE TABLE "vivero" (
  "id_vivero" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) UNIQUE NOT NULL,
  "direccion" varchar(200) NOT NULL,
  "latitud" numeric(9,6) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
  "longitud" numeric(9,6) NOT NULL CHECK (longitud BETWEEN -180 AND 180)
);

CREATE TABLE "zona" (
  "id_vivero" integer NOT NULL,
  "cod_zona" varchar(10) NOT NULL CHECK (cod_zona ~ '^[A-Z0-9]{2,10}$'),
  "nombre" varchar(60) NOT NULL,
  "latitud" numeric(9,6) NOT NULL CHECK (latitud BETWEEN -90 AND 90),
  "longitud" numeric(9,6) NOT NULL CHECK (longitud BETWEEN -180 AND 180),
  PRIMARY KEY ("id_vivero", "cod_zona")
);

CREATE TABLE "producto" (
  "id_producto" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) NOT NULL,
  "categoria" varchar(20) NOT NULL CHECK (categoria IN ('Planta', 'Jardinería', 'Decoración')),
  "precio" numeric(8,2) NOT NULL CHECK (precio > 0),
  "descripcion" text
);

CREATE TABLE "stock" (
  "id_vivero" integer NOT NULL,
  "cod_zona" varchar(10) NOT NULL,
  "id_producto" integer NOT NULL,
  "cantidad_disponible" integer NOT NULL DEFAULT 0 CHECK (cantidad_disponible >= 0),
  PRIMARY KEY ("id_vivero", "cod_zona", "id_producto")
);

CREATE TABLE "empleado" (
  "dni" char(9) PRIMARY KEY,
  "nombre" varchar(50) NOT NULL,
  "apellidos" varchar(100) NOT NULL
);

CREATE TABLE "ocupa_puesto" (
  "dni" char(9) NOT NULL,
  "id_vivero" integer NOT NULL,
  "cod_zona" varchar(10) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_fin" date,
  "tarea" varchar(60) NOT NULL,
  PRIMARY KEY ("dni", "id_vivero", "cod_zona", "fecha_inicio"),
  CONSTRAINT check_fechas CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);

CREATE TABLE "cliente" (
  "id_cliente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nif" char(9) UNIQUE NOT NULL,
  "nombre" varchar(50) NOT NULL,
  "apellidos" varchar(100) NOT NULL
);

CREATE TABLE "cliente_plus" (
  "id_cliente" integer PRIMARY KEY,
  "fecha_ingreso" date NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE "pedido" (
  "id_pedido" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fecha" date NOT NULL DEFAULT CURRENT_DATE,
  "importe_total" numeric(10,2) NOT NULL DEFAULT 0,
  "dni_empleado" char(9) NOT NULL,
  "id_cliente" integer
);

CREATE TABLE "linea_pedido" (
  "id_pedido" integer NOT NULL,
  "id_producto" integer NOT NULL,
  "cantidad" integer NOT NULL CHECK (cantidad > 0),
  "precio_unitario" numeric(8,2) NOT NULL CHECK (precio_unitario >= 0),
  "subtotal" numeric(10,2) GENERATED ALWAYS AS (cantidad * precio_unitario) STORED,
  PRIMARY KEY ("id_pedido", "id_producto")
);

CREATE TABLE "bonificacion" (
  "id_cliente" integer NOT NULL,
  "anio" smallint NOT NULL CHECK (anio >= 2000),
  "mes" smallint NOT NULL CHECK (mes BETWEEN 1 AND 12),
  "volumen_compras" numeric(10,2) NOT NULL DEFAULT 0 CHECK (volumen_compras >= 0),
  "importe_bonificacion" numeric(8,2) NOT NULL DEFAULT 0 CHECK (importe_bonificacion >= 0),
  PRIMARY KEY ("id_cliente", "anio", "mes")
);

-- 2. RELACIONES (LLAVES FORÁNEAS)
ALTER TABLE "zona" 
  ADD FOREIGN KEY ("id_vivero") REFERENCES "vivero" ("id_vivero") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "stock" 
  ADD FOREIGN KEY ("id_vivero", "cod_zona") REFERENCES "zona" ("id_vivero", "cod_zona") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "stock" 
  ADD FOREIGN KEY ("id_producto") REFERENCES "producto" ("id_producto") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ocupa_puesto" 
  ADD FOREIGN KEY ("dni") REFERENCES "empleado" ("dni") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ocupa_puesto" 
  ADD FOREIGN KEY ("id_vivero", "cod_zona") REFERENCES "zona" ("id_vivero", "cod_zona") ON DELETE RESTRICT ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

-- CORREGIDO: cliente_plus apunta a cliente
ALTER TABLE "cliente_plus" 
  ADD FOREIGN KEY ("id_cliente") REFERENCES "cliente" ("id_cliente") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido" 
  ADD FOREIGN KEY ("dni_empleado") REFERENCES "empleado" ("dni") ON DELETE RESTRICT ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido" 
  ADD FOREIGN KEY ("id_cliente") REFERENCES "cliente" ("id_cliente") ON DELETE SET NULL ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "linea_pedido" 
  ADD FOREIGN KEY ("id_pedido") REFERENCES "pedido" ("id_pedido") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "linea_pedido" 
  ADD FOREIGN KEY ("id_producto") REFERENCES "producto" ("id_producto") ON DELETE RESTRICT ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bonificacion" 
  ADD FOREIGN KEY ("id_cliente") REFERENCES "cliente_plus" ("id_cliente") ON DELETE CASCADE ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;